const text = ($json.final_blog_output || "").trim();
const tagNames = [
  "GW_TAG_01_BLOG_IDENTITY","GW_TAG_02_SEO_METADATA","GW_TAG_03_HERO_HOOK","GW_TAG_04_CONTEXT_SETUP",
  "GW_TAG_05_PROBLEM_BREAKDOWN","GW_TAG_06_SOLUTION_OVERVIEW","GW_TAG_07_IMPLEMENTATION_STEPS","GW_TAG_08_CODE_SNIPPETS",
  "GW_TAG_09_CODE_EXPLANATION","GW_TAG_10_VALIDATION_CHECKLIST","GW_TAG_11_EDGE_CASES","GW_TAG_12_BEST_PRACTICES",
  "GW_TAG_13_PRO_TIPS","GW_TAG_14_RESOURCES","GW_TAG_15_FINAL_THOUGHTS","GW_TAG_16_PREVIEW_CARD_DATA","GW_TAG_17_IMAGE_PLAN","GW_TAG_18_KEY_CONCEPTS"
];

const sections = {};
for (let i = 0; i < tagNames.length; i++) {
  const open = `[${tagNames[i]}]`;
  const start = text.indexOf(open);
  if (start === -1) continue;
  const contentStart = start + open.length;
  let end = text.length;
  for (let j = i + 1; j < tagNames.length; j++) {
    const next = text.indexOf(`[${tagNames[j]}]`, contentStart);
    if (next !== -1) { end = next; break; }
  }
  sections[tagNames[i]] = text.slice(contentStart, end).trim();
}

return [{ json: { ...$json, sections, parsed_tag_count: Object.keys(sections).length } }];

const s = $json.sections || {};
const get = (k) => (s[k] || "").trim();

const parseKV = (block) => {
  const out = {};
  (block || "").split("\n").forEach((line) => {
    const m = line.match(/^\s*[-*]?\s*([A-Za-z0-9 _-]+?)\s*:\s*(.+)\s*$/);
    if (m) out[m[1].trim().toLowerCase()] = m[2].trim();
  });
  return out;
};

const bullets = (block) => (block || "")
  .split("\n")
  .map(x => x.trim())
  .filter(x => /^-\s+/.test(x))
  .map(x => x.replace(/^-\s+/, "").trim());

const paragraphs = (block) => (block || "")
  .split(/\n\n+/)
  .map(x => x.trim())
  .filter(Boolean);

const identity = parseKV(get("GW_TAG_01_BLOG_IDENTITY"));
const seo = parseKV(get("GW_TAG_02_SEO_METADATA"));

let title = identity["title"] || "";
let slug = identity["slug"] || "";
if (!slug && title) slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");

const readTimeRaw = seo["suggestedreadtime"] || seo["readtime"] || "8";
const readTime = (readTimeRaw.match(/\d+/) || ["8"])[0];

const hero = paragraphs(get("GW_TAG_03_HERO_HOOK"));
const context = paragraphs(get("GW_TAG_04_CONTEXT_SETUP"));
const problem = bullets(get("GW_TAG_05_PROBLEM_BREAKDOWN"));
const solution = paragraphs(get("GW_TAG_06_SOLUTION_OVERVIEW"));
const steps = (get("GW_TAG_07_IMPLEMENTATION_STEPS") || "")
  .split("\n")
  .map(x => x.trim())
  .filter(x => /^(\*\*\s*)?step\s+\d+/i.test(x) || /^-\s+/.test(x))
  .map(x => x.replace(/^[-*\s]+/, "").trim());

const best = bullets(get("GW_TAG_12_BEST_PRACTICES"));
const tips = bullets(get("GW_TAG_13_PRO_TIPS"));
const finalThoughts = paragraphs(get("GW_TAG_15_FINAL_THOUGHTS"));

const codeRegex = /```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```/g;
const codeRaw = get("GW_TAG_08_CODE_SNIPPETS");
const codeBlocks = [];
let m;
while ((m = codeRegex.exec(codeRaw)) !== null) {
  codeBlocks.push({ language: (m[1] || "text").trim() || "text", code: (m[2] || "").trim() });
}

const resRaw = get("GW_TAG_14_RESOURCES");
const resources = [];
const mdLink = /\[([^\]]+)\]\(([^)]+)\)/g;
let l;
while ((l = mdLink.exec(resRaw)) !== null) resources.push({ label: l[1].trim(), href: l[2].trim() });

const kcRaw = get("GW_TAG_18_KEY_CONCEPTS");
let conceptsTitle = "Key Concepts Covered";
let conceptItems = [];
let highlightTokens = [];
if (kcRaw) {
  const lines = kcRaw.split("\n").map(x => x.trim()).filter(Boolean);
  let mode = "items";
  for (const line of lines) {
    const st = line.match(/^[-*]?\s*sectionTitle\s*:\s*(.+)$/i);
    if (st) { conceptsTitle = st[1].trim(); continue; }
    if (/^[-*]?\s*items\s*:/i.test(line)) { mode = "items"; continue; }
    if (/^[-*]?\s*highlightTokens\s*:/i.test(line)) { mode = "tokens"; continue; }
    if (/^-\s+/.test(line)) {
      const v = line.replace(/^-\s+/, "").trim();
      if (mode === "tokens") highlightTokens.push(v.replace(/^`|`$/g, ""));
      else conceptItems.push(v);
    }
  }
}
if (!conceptItems.length) {
  conceptItems = [
    "Use deterministic server-client rendering and validate in production mode.",
    "Isolate browser-only APIs behind useEffect.",
    "Use dynamic imports with ssr:false for browser-only widgets."
  ];
}
if (!highlightTokens.length) {
  const tokenSet = new Set();
  conceptItems.forEach((item) => {
    const matches = item.match(/`([^`]+)`/g) || [];
    matches.forEach((m) => tokenSet.add(m.replace(/`/g, "")));
  });
  highlightTokens = Array.from(tokenSet);
}

const safeBase = (slug || title || "Generated Blog").replace(/[^a-zA-Z0-9 ]/g, " ").split(/\s+/).filter(Boolean);
const componentName = (safeBase.length ? safeBase : ["Generated","Blog"]).map(x => x[0].toUpperCase() + x.slice(1)).join("") + "Page";

return [{
  json: {
    ...$json,
    title,
    slug,
    readTime,
    componentName,
    hero,
    context,
    problem,
    solution,
    steps,
    best,
    tips,
    finalThoughts,
    codeBlocks,
    resources,
    conceptsTitle,
    conceptItems,
    highlightTokens,
  }
}];

const d = $json;

const q = (v) => JSON.stringify(String(v ?? ""));
const esc = (s) => String(s || "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/\{/g, "&#123;")
  .replace(/\}/g, "&#125;");

const para = (arr) => (arr || []).map((p) => `\n        <BlogContent>{${q(p)}}</BlogContent>`).join("");

const ext = (lang) => {
  const m = { typescript: 'ts', javascript: 'js', tsx: 'tsx', jsx: 'jsx', bash: 'sh', shell: 'sh', dart: 'dart', rust: 'rs', python: 'py', json: 'json', yaml: 'yml', toml: 'toml' };
  const key = String(lang || 'txt').toLowerCase();
  return m[key] || key.replace(/[^a-z0-9]/g, '') || 'txt';
};

const tokenize = (line, tokens) => {
  if (!tokens || !tokens.length) return esc(line);
  let out = esc(line);
  tokens
    .filter(Boolean)
    .sort((a, b) => b.length - a.length)
    .forEach((t) => {
      const safe = t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const re = new RegExp(`(${safe})`, "g");
      out = out.replace(re, `<BlogHighlighter>$1</BlogHighlighter>`);
    });
  return out;
};

const conceptItemsJsx = (d.conceptItems || []).length
  ? d.conceptItems.map((line, i) => `<React.Fragment key={${q(`ci-${i}`)}}>${tokenize(line, d.highlightTokens || [])}</React.Fragment>`).join(",\n              ")
  : `<React.Fragment key=\"ci-0\">Use <BlogHighlighter>useEffect</BlogHighlighter> for browser APIs.</React.Fragment>`;

const conceptChips = (d.highlightTokens || []).length
  ? d.highlightTokens.map((t, i) => `<span key={${q(String(i))}} className=\"inline-flex\"><BlogHighlighter>${esc(t)}</BlogHighlighter></span>`).join("\n            ")
  : `<span key=\"0\" className=\"inline-flex\"><BlogHighlighter>Hydration</BlogHighlighter></span>`;

const resourceItems = (d.resources || []).length
  ? d.resources.map((r, i) => `<Link key={${q(String(i))}} href={${q(r.href)}} target=\"_blank\" rel=\"noopener noreferrer\" className=\"text-sky-400 hover:text-sky-600\">${esc(r.label)}</Link>`).join(",\n            ")
  : `<Link key=\"0\" href=\"https://nextjs.org/docs\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"text-sky-400 hover:text-sky-600\">Next.js Docs</Link>`;

const stepItems = (d.steps || []).length ? d.steps : ["Step 1: Implement solution"];
const codeBlocks = d.codeBlocks || [];
const pairedCount = Math.min(stepItems.length, codeBlocks.length);
const interleavedStepCode = Array.from({ length: pairedCount }).map((_, i) => {
  const step = stepItems[i];
  const block = codeBlocks[i];
  const stepTitle = String(step).replace(/^[-*\s]+/, "").trim();
  return `\n        <BlogSubTitle>{${q(stepTitle)}}</BlogSubTitle>\n        <CodeBlock\n          language=${q(block.language || "text")}\n          filename=${q(`snippet-${i + 1}.${ext(block.language)}`)}\n          code={${q(block.code || "")}}\n        />`;
}).join("\n");

const remainingStepItems = stepItems.slice(pairedCount);
const remainingStepsBlock = remainingStepItems.length
  ? `\n        <BlogSubTitle>Additional Implementation Notes</BlogSubTitle>\n        <BlogList items={[\n              ${remainingStepItems.map((x) => q(x)).join(",\n              ")}\n        ]} />`
  : "";

const listItems = (arr) => (arr && arr.length ? arr.map((x) => q(x)).join(",\n              ") : q("Use deterministic server-client rendering and validate in production mode."));

const title = d.title || "Generated Blog";
const component = d.componentName || "GeneratedBlogPage";

const tsx = `"use client";
import { BlogContent, BlogHighlighter, BlogList, BlogSubTitle, BlogTips, WriterInfo } from "@/app/components/BlogComponents";
import CustomTitle from "@/components/custom/CustomTitle";
import { CodeBlock } from "@/components/ui/code-block";
import { BLOG_AUTHORS, BLOG_PREVIEWS } from "@/lib/constants";
import Link from "next/link";
import { usePathname } from "next/navigation";
import React from "react";
import RelatedNextBlogButton from "@/app/components/RelatedNextBlogButton";
import TagsList from "@/components/custom/TagsList";

const ${component} = () => {
  const author = BLOG_AUTHORS[1];
  const pathname = usePathname().split("/")[2];
  const tags = BLOG_PREVIEWS.find((blog) => blog.slug === pathname)?.tags || [];

  return (
    <div className="min-h-screen text-white p-6 md:p-10 leading-relaxed">
      <div className="max-w-4xl mx-auto space-y-8">
        <header className="md:my-10">
          <TagsList tags={tags} />
          <CustomTitle headingClassName="!text-start" heading={<>{${q(title)}}</>} />
          <WriterInfo image={author.image} name={author.name} role={author.role} readTime={${q(d.readTime || "8")}} date="June 14, 2025" />
        </header>${para(d.hero)}

        <BlogSubTitle>{${q(d.conceptsTitle || "Key Concepts Covered")}}</BlogSubTitle>
        <div className="flex flex-wrap gap-2">
            ${conceptChips}
        </div>
        <BlogList items={[
              ${conceptItemsJsx}
        ]} />

        <BlogSubTitle>Context Setup</BlogSubTitle>${para(d.context)}

        <BlogSubTitle>Problem Breakdown</BlogSubTitle>
        <BlogList items={[
              ${listItems(d.problem)}
        ]} />

        <BlogSubTitle>Solution Overview</BlogSubTitle>${para(d.solution)}
${interleavedStepCode}${remainingStepsBlock}

        <BlogSubTitle>Best Practices</BlogSubTitle>
        <BlogList items={[
              ${listItems(d.best)}
        ]} />

        <BlogSubTitle>Pro Tips</BlogSubTitle>
        <BlogList items={[
              ${listItems(d.tips)}
        ]} />

        <BlogSubTitle>Resources</BlogSubTitle>
        <BlogList items={[
            ${resourceItems}
        ]} />

        <BlogSubTitle>Final Thoughts</BlogSubTitle>${para(d.finalThoughts)}

        <BlogTips title="Pro Tip" description="Validate generated TSX before writing to disk." />
        <RelatedNextBlogButton currentSlug={pathname} currentTags={tags} />
      </div>
    </div>
  );
};

export default ${component};
`;

return [{ json: { ...$json, tsx_file_content: tsx } }];

const code = ($json.tsx_file_content || "").toLowerCase();
const title = ($json.title || "").trim();
const slug = ($json.slug || "").trim();
const componentName = ($json.componentName || "").trim();

const errors = [];

if (!code.includes('"use client";')) errors.push("Missing use client");
if (!/const\s+[a-z0-9_]+\s*=\s*\(\)\s*=>/i.test(code)) errors.push("Missing component declaration");
if (!/export\s+default\s+[a-z0-9_]+;/i.test(code)) errors.push("Missing default export");
if (code.includes("d.title")) errors.push("Unresolved template variable");
if ((code.match(/\{/g) || []).length !== (code.match(/\}/g) || []).length) errors.push("Unbalanced braces");
if ((code.match(/\(/g) || []).length !== (code.match(/\)/g) || []).length) errors.push("Unbalanced parentheses");

if (!title || !slug) errors.push("Missing title/slug extraction");
if (slug.toLowerCase() === "generated-blog") errors.push("Fallback slug in use");
if (componentName.toLowerCase() === "generatedblogpage") errors.push("Fallback component in use");
if (/not provided/i.test(code)) errors.push("Placeholder content present");

const topicOk = code.includes("hydration") && (code.includes("next.js") || code.includes("nextjs"));
if (!topicOk) errors.push("Topic mismatch");

return [{ json: { ...$json, tsx_valid: errors.length === 0, tsx_errors: errors } }];

let s = $json.tsx_file_content || "";
try {
  if (typeof s === "string" && s.startsWith('"') && s.endsWith('"')) s = JSON.parse(s);
} catch (_) {}
return [{ json: { ...$json, tsx_raw: s } }];

const topic = $json.topic || "Understanding and Fixing Hydration Errors in Next.js";
const tsx = `"use client";
import { BlogContent, BlogHighlighter, BlogList, BlogSubTitle, BlogTips, WriterInfo } from "@/app/components/BlogComponents";
import CustomTitle from "@/components/custom/CustomTitle";
import { CodeBlock } from "@/components/ui/code-block";
import { BLOG_AUTHORS, BLOG_PREVIEWS } from "@/lib/constants";
import Link from "next/link";
import { usePathname } from "next/navigation";
import React from "react";
import RelatedNextBlogButton from "@/app/components/RelatedNextBlogButton";
import TagsList from "@/components/custom/TagsList";

const NextjsHydrationErrorsFixPage = () => {
  const author = BLOG_AUTHORS[1];
  const pathname = usePathname().split("/")[2];
  const tags = BLOG_PREVIEWS.find((blog) => blog.slug === pathname)?.tags || [];

  return (
    <div className="min-h-screen text-white p-6 md:p-10 leading-relaxed">
      <div className="max-w-4xl mx-auto space-y-8">
        <header className="md:my-10">
          <TagsList tags={tags} />
          <CustomTitle headingClassName="!text-start" heading={<>{"Understanding and Fixing Hydration Errors in Next.js"}</>} />
          <WriterInfo image={author.image} name={author.name} role={author.role} readTime={"8"} date="June 14, 2025" />
        </header>

        <BlogContent>{"Hydration errors happen when server-rendered HTML differs from the first client render."}</BlogContent>

        <BlogSubTitle>Key Concepts Covered</BlogSubTitle>
        <div className="flex flex-wrap gap-2">
          <span className="inline-flex"><BlogHighlighter>Hydration</BlogHighlighter></span>
          <span className="inline-flex"><BlogHighlighter>useEffect</BlogHighlighter></span>
          <span className="inline-flex"><BlogHighlighter>dynamic import</BlogHighlighter></span>
        </div>
        <BlogList items={[
          <>Use <BlogHighlighter>useEffect</BlogHighlighter> for browser-only APIs.</>,
          <>Keep server and client render output deterministic.</>,
          <>Use <BlogHighlighter>ssr: false</BlogHighlighter> for browser-only widgets.</>
        ]} />

        <BlogSubTitle>Context Setup</BlogSubTitle>
        <BlogContent>{"React hydration expects identical initial markup from server and client."}</BlogContent>

        <BlogSubTitle>Solution Overview</BlogSubTitle>
        <BlogContent>{"Fix mismatches by deferring browser-only logic and stabilizing first render."}</BlogContent>

        <BlogSubTitle>Step 1: Move browser-only access to useEffect</BlogSubTitle>
        <CodeBlock
          language="typescript"
          filename="snippet-1.tsx"
          code={`"use client";
import { useEffect, useState } from "react";

export default function WidthInfo() {
  const [width, setWidth] = useState<number | null>(null);
  useEffect(() => {
    const update = () => setWidth(window.innerWidth);
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);
  return <div>{width === null ? "Loading..." : `Width: ${width}`}</div>;
}`}
        />

        <BlogSubTitle>Step 2: Isolate browser-only component with dynamic import</BlogSubTitle>
        <CodeBlock
          language="typescript"
          filename="snippet-2.tsx"
          code={`import dynamic from "next/dynamic";
const Chart = dynamic(() => import("./Chart"), { ssr: false });
export default function DashboardChart() { return <Chart />; }`}
        />

        <BlogSubTitle>Best Practices</BlogSubTitle>
        <BlogList items={[
          "Keep initial render deterministic",
          "Avoid window/document/localStorage in server render",
          "Validate in production mode"
        ]} />

        <BlogSubTitle>Resources</BlogSubTitle>
        <BlogList items={[
          <Link key="0" href="https://nextjs.org/docs/messages/react-hydration-error" target="_blank" rel="noopener noreferrer" className="text-sky-400 hover:text-sky-600">Next.js Hydration Error Docs</Link>
        ]} />

        <BlogSubTitle>Final Thoughts</BlogSubTitle>
        <BlogContent>{"Treat hydration warnings as architectural signals and fix root causes early."}</BlogContent>

        <BlogTips title="Pro Tip" description="Treat hydration warnings as release blockers for critical pages." />
        <RelatedNextBlogButton currentSlug={pathname} currentTags={tags} />
      </div>
    </div>
  );
};

export default NextjsHydrationErrorsFixPage;
`;

return [{
  json: {
    ...$json,
    topic,
    tsx_slug: "nextjs-hydration-errors-fix",
    tsx_component_name: "NextjsHydrationErrorsFixPage",
    tsx_raw: tsx,
    tsx_file_content: tsx,
    tsx_valid: true,
    tsx_errors_json: "[]",
    generation_path: "fallback_deterministic"
  }
}];
